params.spec:
{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "description": "The top 12 identities (fewer on a narrow panel, down to 8) by signal volume, one tile per identity, in a block per kind (named API key, person, cloud API key, platform, user with no email, unattributed); the rest of each kind is folded into one grey \"+N more\" tile. Area grows with the square root of event volume plus the same small share for every tile, so a quiet identity keeps a readable name but never outgrows a busier one; each tile prints its event count where it fits, at the largest of three sizes that still fits the name and its count (14px on a tile at least 200x100, else 12px, else 10px; a name too long to break at its separators is shortened with an ellipsis and the tooltip has it in full); colour is Risk total (risk weight × events, the quantity the risk leaderboard ranks by) on a square-root scale. A key owner that is an opaque Cloud API key id is shown in the suite's one form for it. Grouped on raw fields first and resolved afterwards, so an identity whose events disagree about its kind is still one tile, in its most specific block.",
  "autosize": {
    "type": "fit",
    "contains": "padding"
  },
  "padding": 4,
  "signals": [
    {
      "name": "empty",
      "update": "length(data('raw')) === 0"
    },
    {
      "name": "keep",
      "update": "max(8, min(12, floor(width / 70)))"
    }
  ],
  "data": [
    {
      "name": "raw",
      "url": {
        "%type%": "esql",
        "query": "FROM logs-elastic_cloud.serverless_audit.otel-* | WHERE @timestamp <= ?_tend AND @timestamp > ?_tstart | WHERE (attributes.elasticsearch.audit.action IS NULL OR NOT (attributes.elasticsearch.audit.action IN (\"cluster:monitor/main\", \"elastic.maintenance\") OR attributes.elasticsearch.audit.action LIKE \"indices:data/read/search*\" OR attributes.elasticsearch.audit.action LIKE \"indices:data/read/msearch*\" OR attributes.elasticsearch.audit.action LIKE \"indices:data/read/scroll*\" OR attributes.elasticsearch.audit.action LIKE \"indices:data/read/*point_in_time\" OR attributes.elasticsearch.audit.action == \"indices:data/read/open_reader_context\" OR attributes.elasticsearch.audit.action LIKE \"indices:data/read/esql*\" OR attributes.elasticsearch.audit.action LIKE \"indices:admin/esql/*\" OR attributes.elasticsearch.audit.action LIKE \"indices:data/read/field_caps*\" OR attributes.elasticsearch.audit.action LIKE \"indices:data/read/async_search/*\" OR attributes.elasticsearch.audit.action LIKE \"indices:admin/resolve/*\" OR attributes.elasticsearch.audit.action == \"indices:admin/shards/search_shards\" OR attributes.elasticsearch.audit.action LIKE \"cluster:monitor/xpack/esql/*\" OR attributes.elasticsearch.audit.action IN (\"cluster:monitor/project/tags\", \"cluster:monitor/xpack/inference/get\", \"cluster:admin/xpack/security/api_key/get\", \"cluster:admin/xpack/security/api_key/query\"))) AND (attributes.event.action IS NULL OR NOT (attributes.event.action IN (\"authentication_success\",\"connection_granted\") OR attributes.event.action IN (\"saved_object_open_point_in_time\",\"saved_object_close_point_in_time\",\"space_get\",\"space_find\") OR (attributes.event.action == \"http_request\" AND attributes.url.original IS NOT NULL AND attributes.url.original RLIKE \"https?://[^/]+(/s/[^/]+)?/((internal|translations|app)/.*|api/content_management/rpc/(get|search|mget|bulkGet).*|bootstrap(-anonymous)?[.]js.*|api/(core|licensing|banners|ui_counters)/.*|api/spaces/space([?].*)?)|https?://[^/]+(/s/[^/]+)?/api/(saved_objects/(_import|_export)|[^?]*/(elastic_)?cloud-audit-).*\") OR (attributes.kibana.saved_object.type IS NOT NULL AND ((attributes.event.action == \"saved_object_get\" AND attributes.kibana.saved_object.type IN (\"config\",\"config-global\")) OR (attributes.event.action == \"saved_object_find\" AND attributes.kibana.saved_object.type == \"index-pattern\"))) OR (attributes.kibana.saved_object.id IS NOT NULL AND (attributes.kibana.saved_object.id LIKE \"cloud-audit-*\" OR attributes.kibana.saved_object.id LIKE \"elastic_cloud-audit-*\") AND (attributes.event.action IN (\"saved_object_get\",\"saved_object_resolve\",\"saved_object_find\") OR attributes.kibana.session.id IS NULL)))) | STATS n = COUNT(*) BY attributes.api_key.name, attributes.user.email, attributes.user.name, attributes.user.domain, attributes.event.action, scc = attributes.elasticsearch.audit.security_config_change IS NOT NULL, attributes.event.outcome, resource.attributes.service.name, et = MV_CONCAT(attributes.event.type, \",\"), housekeeping = (attributes.event.action IS NOT NULL AND attributes.event.action == \"invalidate_apikeys\" AND attributes.user.name IS NOT NULL AND attributes.user.name IN (\"elastic.maintenance\",\"autoscaling\",\"elasticsearch-controller\",\"elastic/fleet-server\",\"elastic/kibana\") AND attributes.api_key.name IS NULL) | EVAL attributes.event.type = SPLIT(et, \",\"), attributes.elasticsearch.audit.security_config_change = CASE(scc, \"present\") | EVAL risk = CASE(housekeeping, 0, attributes.event.action == \"invalidate_apikeys\", 45, attributes.event.action == \"anonymous_access_denied\", 35, attributes.elasticsearch.audit.security_config_change IS NOT NULL, 50, attributes.event.outcome == \"failure\", 40, (resource.attributes.service.name == \"serverless-kibana\" AND ((attributes.event.type IN (\"change\",\"creation\",\"deletion\") AND (attributes.event.action IS NULL OR NOT (attributes.event.action IN (\"saved_object_open_point_in_time\",\"saved_object_close_point_in_time\")))) OR attributes.event.action IN (\"rule_run_soon\",\"secret_create\"))) AND attributes.event.action IN (\"workflow_run\",\"workflow_test\",\"workflow_execution_cancel\"), 10, (resource.attributes.service.name == \"serverless-kibana\" AND ((attributes.event.type IN (\"change\",\"creation\",\"deletion\") AND (attributes.event.action IS NULL OR NOT (attributes.event.action IN (\"saved_object_open_point_in_time\",\"saved_object_close_point_in_time\")))) OR attributes.event.action IN (\"rule_run_soon\",\"secret_create\"))) AND (attributes.event.type == \"deletion\" OR attributes.event.action == \"rule_disable\"), 30, (resource.attributes.service.name == \"serverless-kibana\" AND ((attributes.event.type IN (\"change\",\"creation\",\"deletion\") AND (attributes.event.action IS NULL OR NOT (attributes.event.action IN (\"saved_object_open_point_in_time\",\"saved_object_close_point_in_time\")))) OR attributes.event.action IN (\"rule_run_soon\",\"secret_create\"))), 25, 0) | STATS events = SUM(n), severity = SUM(risk * n), scoring = SUM(CASE(risk > 0, n, 0)), authed = SUM(CASE(attributes.event.outcome IS NULL OR attributes.event.outcome != \"failure\", n, 0)) BY attributes.api_key.name, attributes.user.email, attributes.user.name, attributes.user.domain | EVAL actor = CASE(attributes.api_key.name IS NOT NULL, attributes.api_key.name, COALESCE(attributes.user.email, attributes.user.name, \"<anonymous>\")), kind_rank = CASE(attributes.api_key.name IS NOT NULL, 6, attributes.user.email IS NOT NULL, 5, attributes.user.domain == \"_cloud_api_key\" OR (LENGTH(attributes.user.name) == 20 AND attributes.user.name RLIKE \"[-_A-Za-z0-9]{20}\" AND NOT attributes.user.name RLIKE \"[0-9]{20}\"), 4, attributes.user.domain == \"_service_account\" OR attributes.user.name IN (\"elastic.maintenance\",\"autoscaling\",\"elasticsearch-controller\",\"elastic/fleet-server\",\"elastic/kibana\"), 3, attributes.user.name IS NOT NULL AND NOT attributes.user.name IN (\"<anonymous>\",\"<unauthenticated-cloud-access-token>\",\"<unauthenticated-saml-user>\",\"<unauthenticated-cloud-api-key>\") AND authed > 0, 2, 1), owner = CASE(attributes.api_key.name IS NOT NULL, COALESCE(attributes.user.email, attributes.user.name), null) | STATS events = SUM(events), severity = SUM(severity), scoring = SUM(scoring), kind_rank = MAX(kind_rank), owner = MAX(owner) BY actor | EVAL actor_kind = CASE(kind_rank == 6, \"named API key\", kind_rank == 5, \"person\", kind_rank == 4, \"cloud API key\", kind_rank == 3, \"platform\", kind_rank == 2, \"user, no email\", \"unattributed\") | SORT events DESC | LIMIT 500 | KEEP actor, actor_kind, owner, events, severity, scoring | EVAL actor = CASE((LENGTH(actor) == 20 AND actor RLIKE \"[-_A-Za-z0-9]{20}\" AND NOT actor RLIKE \"[0-9]{20}\"), CONCAT(LEFT(actor, 5), \"… · Cloud API key\"), actor) | EVAL owner = CASE((LENGTH(owner) == 20 AND owner RLIKE \"[-_A-Za-z0-9]{20}\" AND NOT owner RLIKE \"[0-9]{20}\"), CONCAT(LEFT(owner, 5), \"… · Cloud API key\"), owner)",
        "%timefield%": "@timestamp",
        "%context%": true
      }
    },
    {
      "name": "ranked",
      "source": "raw",
      "transform": [
        {
          "type": "window",
          "sort": {
            "field": "events",
            "order": "descending"
          },
          "ops": [
            "row_number"
          ],
          "as": [
            "rank"
          ]
        },
        {
          "type": "formula",
          "as": "folded",
          "expr": "false"
        },
        {
          "type": "formula",
          "as": "members",
          "expr": "1"
        }
      ]
    },
    {
      "name": "kept",
      "source": "ranked",
      "transform": [
        {
          "type": "filter",
          "expr": "datum.rank <= keep"
        }
      ]
    },
    {
      "name": "rest",
      "source": "ranked",
      "transform": [
        {
          "type": "filter",
          "expr": "datum.rank > keep"
        },
        {
          "type": "aggregate",
          "groupby": [
            "actor_kind"
          ],
          "ops": [
            "sum",
            "sum",
            "sum",
            "count"
          ],
          "fields": [
            "events",
            "severity",
            "scoring",
            null
          ],
          "as": [
            "events",
            "severity",
            "scoring",
            "members"
          ]
        },
        {
          "type": "formula",
          "as": "actor",
          "expr": "'+' + datum.members + ' more'"
        },
        {
          "type": "formula",
          "as": "owner",
          "expr": "null"
        },
        {
          "type": "formula",
          "as": "folded",
          "expr": "true"
        }
      ]
    },
    {
      "name": "sized",
      "source": [
        "kept",
        "rest"
      ],
      "transform": [
        {
          "type": "formula",
          "as": "root",
          "expr": "sqrt(datum.events)"
        },
        {
          "type": "joinaggregate",
          "ops": [
            "sum",
            "count"
          ],
          "fields": [
            "root",
            "root"
          ],
          "as": [
            "root_total",
            "n"
          ]
        },
        {
          "type": "formula",
          "as": "area",
          "expr": "datum.root + datum.root_total * 0.3 / datum.n"
        }
      ]
    },
    {
      "name": "tree",
      "source": "sized",
      "transform": [
        {
          "type": "nest",
          "keys": [
            "actor_kind"
          ],
          "generate": true
        },
        {
          "type": "treemap",
          "field": "area",
          "sort": {
            "field": "value",
            "order": "descending"
          },
          "round": true,
          "method": "squarify",
          "paddingInner": 3,
          "paddingTop": 15,
          "size": [
            {
              "signal": "width"
            },
            {
              "signal": "height + 15"
            }
          ]
        },
        {
          "type": "formula",
          "as": "y0",
          "expr": "datum.y0 - 15"
        },
        {
          "type": "formula",
          "as": "y1",
          "expr": "datum.y1 - 15"
        }
      ]
    },
    {
      "name": "kinds",
      "source": "sized",
      "transform": [
        {
          "type": "aggregate",
          "groupby": [
            "actor_kind"
          ],
          "ops": [
            "sum"
          ],
          "fields": [
            "members"
          ],
          "as": [
            "kn"
          ]
        }
      ]
    },
    {
      "name": "blocks",
      "source": "tree",
      "transform": [
        {
          "type": "filter",
          "expr": "datum.depth === 1"
        },
        {
          "type": "lookup",
          "from": "kinds",
          "key": "actor_kind",
          "fields": [
            "key"
          ],
          "values": [
            "kn"
          ]
        },
        {
          "type": "formula",
          "as": "header",
          "expr": "(datum.x1 - datum.x0) >= (length(datum.key) + 5) * 6.4 ? datum.key + ' · ' + datum.kn : (datum.x1 - datum.x0) >= length(datum.key) * 6.4 ? datum.key : ''"
        }
      ]
    },
    {
      "name": "leaves",
      "source": "tree",
      "transform": [
        {
          "type": "filter",
          "expr": "!datum.children"
        },
        {
          "type": "formula",
          "as": "tw",
          "expr": "datum.x1 - datum.x0"
        },
        {
          "type": "formula",
          "as": "th",
          "expr": "datum.y1 - datum.y0"
        },
        {
          "type": "formula",
          "as": "count",
          "expr": "format(datum.events, ',') + (datum.events === 1 ? ' event' : ' events')"
        },
        {
          "type": "formula",
          "as": "label",
          "expr": "datum.folded && length(datum.actor) > max(1, floor((datum.tw - 8) / 6)) ? '+' + datum.members : datum.actor"
        },
        {
          "type": "formula",
          "as": "a_cpl",
          "expr": "max(1, floor((datum.tw - 8) / (12 * 0.6)))"
        },
        {
          "type": "formula",
          "as": "a_rows",
          "expr": "floor((datum.th - 4) / (14.4))"
        },
        {
          "type": "formula",
          "as": "a_b1",
          "expr": "length(datum.label) <= datum.a_cpl ? length(datum.label) : (indexof(datum.label, '@') >= 1 && indexof(datum.label, '@') <= datum.a_cpl && length(datum.label) - indexof(datum.label, '@') <= datum.a_cpl) ? indexof(datum.label, '@') : (indexof(datum.label, '@') >= 1 && indexof(datum.label, '@') < datum.a_cpl && length(datum.label) - indexof(datum.label, '@') - 1 <= datum.a_cpl) ? indexof(datum.label, '@') + 1 : max(lastindexof(substring(datum.label, 0, datum.a_cpl), '-'), lastindexof(substring(datum.label, 0, datum.a_cpl), '.'), lastindexof(substring(datum.label, 0, datum.a_cpl), '@'), lastindexof(substring(datum.label, 0, datum.a_cpl), '_'), lastindexof(substring(datum.label, 0, datum.a_cpl), '/'), lastindexof(substring(datum.label, 0, datum.a_cpl), ' ')) >= 1 ? max(lastindexof(substring(datum.label, 0, datum.a_cpl), '-'), lastindexof(substring(datum.label, 0, datum.a_cpl), '.'), lastindexof(substring(datum.label, 0, datum.a_cpl), '@'), lastindexof(substring(datum.label, 0, datum.a_cpl), '_'), lastindexof(substring(datum.label, 0, datum.a_cpl), '/'), lastindexof(substring(datum.label, 0, datum.a_cpl), ' ')) + 1 : datum.a_cpl"
        },
        {
          "type": "formula",
          "as": "a_l1",
          "expr": "substring(datum.label, 0, datum.a_b1)"
        },
        {
          "type": "formula",
          "as": "a_r1",
          "expr": "substring(datum.label, datum.a_b1)"
        },
        {
          "type": "formula",
          "as": "a_b2",
          "expr": "length(datum.a_r1) <= datum.a_cpl ? length(datum.a_r1) : (indexof(datum.a_r1, '@') >= 1 && indexof(datum.a_r1, '@') <= datum.a_cpl && length(datum.a_r1) - indexof(datum.a_r1, '@') <= datum.a_cpl) ? indexof(datum.a_r1, '@') : (indexof(datum.a_r1, '@') >= 1 && indexof(datum.a_r1, '@') < datum.a_cpl && length(datum.a_r1) - indexof(datum.a_r1, '@') - 1 <= datum.a_cpl) ? indexof(datum.a_r1, '@') + 1 : max(lastindexof(substring(datum.a_r1, 0, datum.a_cpl), '-'), lastindexof(substring(datum.a_r1, 0, datum.a_cpl), '.'), lastindexof(substring(datum.a_r1, 0, datum.a_cpl), '@'), lastindexof(substring(datum.a_r1, 0, datum.a_cpl), '_'), lastindexof(substring(datum.a_r1, 0, datum.a_cpl), '/'), lastindexof(substring(datum.a_r1, 0, datum.a_cpl), ' ')) >= 1 ? max(lastindexof(substring(datum.a_r1, 0, datum.a_cpl), '-'), lastindexof(substring(datum.a_r1, 0, datum.a_cpl), '.'), lastindexof(substring(datum.a_r1, 0, datum.a_cpl), '@'), lastindexof(substring(datum.a_r1, 0, datum.a_cpl), '_'), lastindexof(substring(datum.a_r1, 0, datum.a_cpl), '/'), lastindexof(substring(datum.a_r1, 0, datum.a_cpl), ' ')) + 1 : datum.a_cpl"
        },
        {
          "type": "formula",
          "as": "a_l2",
          "expr": "substring(datum.a_r1, 0, datum.a_b2)"
        },
        {
          "type": "formula",
          "as": "a_r2",
          "expr": "substring(datum.a_r1, datum.a_b2)"
        },
        {
          "type": "formula",
          "as": "a_b3",
          "expr": "length(datum.a_r2) <= datum.a_cpl ? length(datum.a_r2) : (indexof(datum.a_r2, '@') >= 1 && indexof(datum.a_r2, '@') <= datum.a_cpl && length(datum.a_r2) - indexof(datum.a_r2, '@') <= datum.a_cpl) ? indexof(datum.a_r2, '@') : (indexof(datum.a_r2, '@') >= 1 && indexof(datum.a_r2, '@') < datum.a_cpl && length(datum.a_r2) - indexof(datum.a_r2, '@') - 1 <= datum.a_cpl) ? indexof(datum.a_r2, '@') + 1 : max(lastindexof(substring(datum.a_r2, 0, datum.a_cpl), '-'), lastindexof(substring(datum.a_r2, 0, datum.a_cpl), '.'), lastindexof(substring(datum.a_r2, 0, datum.a_cpl), '@'), lastindexof(substring(datum.a_r2, 0, datum.a_cpl), '_'), lastindexof(substring(datum.a_r2, 0, datum.a_cpl), '/'), lastindexof(substring(datum.a_r2, 0, datum.a_cpl), ' ')) >= 1 ? max(lastindexof(substring(datum.a_r2, 0, datum.a_cpl), '-'), lastindexof(substring(datum.a_r2, 0, datum.a_cpl), '.'), lastindexof(substring(datum.a_r2, 0, datum.a_cpl), '@'), lastindexof(substring(datum.a_r2, 0, datum.a_cpl), '_'), lastindexof(substring(datum.a_r2, 0, datum.a_cpl), '/'), lastindexof(substring(datum.a_r2, 0, datum.a_cpl), ' ')) + 1 : datum.a_cpl"
        },
        {
          "type": "formula",
          "as": "a_l3",
          "expr": "substring(datum.a_r2, 0, datum.a_b3)"
        },
        {
          "type": "formula",
          "as": "a_r3",
          "expr": "substring(datum.a_r2, datum.a_b3)"
        },
        {
          "type": "formula",
          "as": "a_nl",
          "expr": "datum.a_r1 === '' ? 1 : datum.a_r2 === '' ? 2 : 3"
        },
        {
          "type": "formula",
          "as": "a_hard",
          "expr": "(datum.a_r1 !== '' && indexof('-._@/ ', substring(datum.a_l1, length(datum.a_l1) - 1)) < 0 && substring(datum.a_r1, 0, 1) !== '@') || (datum.a_r2 !== '' && indexof('-._@/ ', substring(datum.a_l2, length(datum.a_l2) - 1)) < 0 && substring(datum.a_r2, 0, 1) !== '@')"
        },
        {
          "type": "formula",
          "as": "a_ok",
          "expr": "!datum.a_hard && datum.a_r3 === '' && datum.a_nl <= datum.a_rows && datum.th >= 18.4"
        },
        {
          "type": "formula",
          "as": "a_cnt",
          "expr": "datum.a_rows > datum.a_nl && length(format(datum.events, ',')) <= datum.a_cpl"
        },
        {
          "type": "formula",
          "as": "a_own",
          "expr": "datum.owner != null && datum.a_rows > datum.a_nl + (datum.a_cnt ? 1 : 0) && length(datum.owner) + 7 <= datum.a_cpl"
        },
        {
          "type": "formula",
          "as": "a_lines",
          "expr": "split(join(slice([datum.a_l1, datum.a_l2, datum.a_l3], 0, datum.a_nl), '\\n') + (datum.a_cnt ? '\\n' + (length(datum.count) <= datum.a_cpl ? datum.count : format(datum.events, ',')) : '') + (datum.a_own ? '\\nowner: ' + datum.owner : ''), '\\n')"
        },
        {
          "type": "formula",
          "as": "c_cpl",
          "expr": "max(1, floor((datum.tw - 8) / (14 * 0.6)))"
        },
        {
          "type": "formula",
          "as": "c_rows",
          "expr": "floor((datum.th - 4) / (16.8))"
        },
        {
          "type": "formula",
          "as": "c_b1",
          "expr": "length(datum.label) <= datum.c_cpl ? length(datum.label) : (indexof(datum.label, '@') >= 1 && indexof(datum.label, '@') <= datum.c_cpl && length(datum.label) - indexof(datum.label, '@') <= datum.c_cpl) ? indexof(datum.label, '@') : (indexof(datum.label, '@') >= 1 && indexof(datum.label, '@') < datum.c_cpl && length(datum.label) - indexof(datum.label, '@') - 1 <= datum.c_cpl) ? indexof(datum.label, '@') + 1 : max(lastindexof(substring(datum.label, 0, datum.c_cpl), '-'), lastindexof(substring(datum.label, 0, datum.c_cpl), '.'), lastindexof(substring(datum.label, 0, datum.c_cpl), '@'), lastindexof(substring(datum.label, 0, datum.c_cpl), '_'), lastindexof(substring(datum.label, 0, datum.c_cpl), '/'), lastindexof(substring(datum.label, 0, datum.c_cpl), ' ')) >= 1 ? max(lastindexof(substring(datum.label, 0, datum.c_cpl), '-'), lastindexof(substring(datum.label, 0, datum.c_cpl), '.'), lastindexof(substring(datum.label, 0, datum.c_cpl), '@'), lastindexof(substring(datum.label, 0, datum.c_cpl), '_'), lastindexof(substring(datum.label, 0, datum.c_cpl), '/'), lastindexof(substring(datum.label, 0, datum.c_cpl), ' ')) + 1 : datum.c_cpl"
        },
        {
          "type": "formula",
          "as": "c_l1",
          "expr": "substring(datum.label, 0, datum.c_b1)"
        },
        {
          "type": "formula",
          "as": "c_r1",
          "expr": "substring(datum.label, datum.c_b1)"
        },
        {
